def prime_fib(n: int):
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")

    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        import math
        limit = math.isqrt(num)
        for i in range(3, limit + 1, 2):
            if num % i == 0:
                return False
        return True

    a, b = 1, 2
    count = 0
    while True:
        if is_prime(a):
            count += 1
            if count == n:
                return a
        a, b = b, a + b
